package io.fireflysoftware.experience.finance.terminal.web.owner;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
import org.fireflyframework.security.spi.PolicyDecisionPort;import org.fireflyframework.security.api.domain.Decision;import org.fireflyframework.security.adapter.opa.OpaPolicyDecisionAdapter;
import org.springframework.boot.autoconfigure.AutoConfigurations;import org.springframework.boot.test.context.runner.ReactiveWebApplicationContextRunner;import org.springframework.context.annotation.*;import reactor.core.publisher.Mono;
class TerminalOwnerPolicyConfigurationTest{
 ReactiveWebApplicationContextRunner runner(){return new ReactiveWebApplicationContextRunner().withConfiguration(AutoConfigurations.of(TerminalOwnerPolicyAutoConfiguration.class));}
 static class ExistingBackend{@Bean PolicyDecisionPort existingPolicy(){return(p,a,r,c)->Mono.just(Decision.deny("Existing backend retained"));}}
 @org.springframework.boot.context.properties.ConfigurationPropertiesScan(basePackageClasses=TerminalOwnerPolicyProperties.class)
 @ComponentScan(basePackageClasses=TerminalOwnerPolicyProperties.class,excludeFilters=@ComponentScan.Filter(type=FilterType.CUSTOM,classes=org.springframework.boot.autoconfigure.AutoConfigurationExcludeFilter.class))static class ActualScan{}
 @Test void disabledFeatureDoesNotBindUnusedPolicy(){runner().withPropertyValues("firefly.terminal.bank-owner.enabled=false","firefly.terminal.bank-owner.policy.base-uri=invalid").run(c->{assertNull(c.getStartupFailure());assertTrue(c.getBeansOfType(PolicyDecisionPort.class).isEmpty());});}
 @Test void enabledFeatureUsesTheRealOpaAdapter(){runner().withPropertyValues("firefly.terminal.bank-owner.enabled=true","firefly.terminal.bank-owner.policy.base-uri=https://policy.invalid","firefly.terminal.bank-owner.policy.decision-path=firefly/owner/allow").run(c->{assertNull(c.getStartupFailure());assertInstanceOf(OpaPolicyDecisionAdapter.class,c.getBean(PolicyDecisionPort.class));});}
 @Test void missingRequiredEndpointFailsClosed(){runner().withPropertyValues("firefly.terminal.bank-owner.enabled=true").run(c->assertNotNull(c.getStartupFailure()));}
 @Test void explicitExistingBackendPreventsUnusedBinding(){runner().withUserConfiguration(ExistingBackend.class).withPropertyValues("firefly.terminal.bank-owner.enabled=true","firefly.terminal.bank-owner.policy.base-uri=invalid").run(c->{assertNull(c.getStartupFailure());assertSame(c.getBean("existingPolicy"),c.getBean(PolicyDecisionPort.class));});}
 @Test void productionScansCannotActivateDisabledNestedBackend(){new ReactiveWebApplicationContextRunner().withUserConfiguration(ActualScan.class).withPropertyValues("firefly.terminal.bank-owner.enabled=false","firefly.terminal.bank-owner.policy.base-uri=invalid").run(c->{assertNull(c.getStartupFailure());assertTrue(c.getBeansOfType(PolicyDecisionPort.class).isEmpty());});}
 @Test void importMetadataContainsProductionPolicy(){assertTrue(org.springframework.boot.context.annotation.ImportCandidates.load(org.springframework.boot.autoconfigure.AutoConfiguration.class,getClass().getClassLoader()).getCandidates().contains(TerminalOwnerPolicyAutoConfiguration.class.getName()));}
 @Test void nestedDefaultIsNotAnIndependentComponent(){assertFalse(TerminalOwnerPolicyAutoConfiguration.DefaultPolicyBackend.class.isAnnotationPresent(Configuration.class));assertFalse(TerminalOwnerPolicyAutoConfiguration.DefaultPolicyBackend.class.isAnnotationPresent(org.springframework.stereotype.Component.class));}
 @Test void nativeResourceServerBacksOffToActualCurrentPolicy(){runner().withConfiguration(AutoConfigurations.of(org.fireflyframework.security.rs.ResourceServerAutoConfiguration.class,org.springframework.boot.security.autoconfigure.web.reactive.ReactiveWebSecurityAutoConfiguration.class)).withPropertyValues("firefly.terminal.bank-owner.enabled=true","firefly.terminal.bank-owner.policy.base-uri=https://policy.invalid","firefly.terminal.bank-owner.policy.decision-path=firefly/owner/allow","firefly.security.resource-server.strict-policy=true").run(c->{assertNull(c.getStartupFailure());assertEquals(1,c.getBeansOfType(PolicyDecisionPort.class).size());assertInstanceOf(OpaPolicyDecisionAdapter.class,c.getBean(PolicyDecisionPort.class));assertNotNull(c.getBean(org.fireflyframework.security.spi.SecurityContextPort.class));});}
}
